JOIN divisions d ON d.code=v.division_code
ON CONFLICT (seed_key) WHERE seed_key IS NOT NULL DO UPDATE SET
    category=EXCLUDED.category,
    division_id=EXCLUDED.division_id,
    prompt=EXCLUDED.prompt,
    question_text=EXCLUDED.question_text,
    correct_answer=EXCLUDED.correct_answer,
    dummy_answers=EXCLUDED.dummy_answers,
    is_active=TRUE,
    sort_order=EXCLUDED.sort_order,
    assessment_kind=EXCLUDED.assessment_kind,
    question_content=EXCLUDED.question_content,
    correct_answer_content=EXCLUDED.correct_answer_content,
    dummy_answer_contents=EXCLUDED.dummy_answer_contents,
    assessment_metadata=EXCLUDED.assessment_metadata,
    year_level=EXCLUDED.year_level;

COMMIT;

-- Verification: each current AITS division should report at least 50 active division questions.
SELECT d.code,d.name,COUNT(q.id) AS active_quiz_questions
FROM divisions d
LEFT JOIN assessment_questions q ON q.division_id=d.id AND q.is_active=TRUE AND q.category='division'
WHERE d.code IN ('codehex','illustrados','neo-tech')
GROUP BY d.id,d.code,d.name
ORDER BY d.sort_order,d.id;

SELECT account_id,member_number FROM member_profiles
WHERE account_id=77 OR member_number='DEVTEST-000077';
